function applyTemplate(tpl, boardId, offset={x:40,y:40}){ const items=tpl.build(); const mkEl=(it, parentId, section, index, pos)=>{ let e; switch(it.type){ case 'column': e=mk('column',{content:{title:it.title,collapsed:false}}); break; case 'note': e=mk('note',{content:{html:it.html}}); break; case 'tasks': e=mk('tasks',{content:{title:it.title}}); break; case 'image': e=mk('image',{content:{blobId:null,url:null,w:0,h:0,caption:it.caption}}); break; case 'link': e=mk('link',{content:{url:it.url,title:it.title,preview:null}}); break; case 'board': { const isI=(window.__BOARD_ICONS||[]).includes(it.emoji); e=mk('board',{content:{title:it.title,cover:null,icon:isI?it.emoji:null,emoji:isI?null:(it.emoji||null),bg:null},color:it.color||null}); break; } case 'swatch': e=mk('swatch',{content:{hex:it.hex}}); break; default: return; } e.parentId=parentId; e.section=section; if(section==='canvas'){ e.x=snap(offset.x+(pos?.x||0)); e.y=snap(offset.y+(pos?.y||0)); e.z=maxZ(parentId)+1+index; if(it.w) e.w=it.w; } else { e.index=index; } S.els[e.id]=e; if(it.type==='column') (it.items||[]).forEach((k,i)=>mkEl(k,e.id,'list',i)); if(it.type==='tasks') (it.items||[]).forEach((t,i)=>{ const k=mk('task',{parentId:e.id,section:'list',index:i,content:{text:t,done:false}}); S.els[k.id]=k; }); return e; }; items.forEach((it,i)=>mkEl(it, boardId, 'canvas', i, it)); }
function templateGrid(onPick){ return `<div class="tpl">${TEMPLATES.map(t=>`<button data-t="${t.id}"><div class="th">${t.th||'<i class="s"></i>'}</div><b>${t.name}</b><small>${t.desc}</small></button>`).join('')}</div>`; }
function askTemplate(boardId){ modal(`<h2>New board</h2><p>Start blank or pick a template.</p>${templateGrid()}`,'wide'); $('#modal-box').onclick=ev=>{ const b=ev.target.closest('[data-t]'); if(!b) return; const tpl=TEMPLATES.find(t=>t.id===b.dataset.t); closeModal(); if(tpl.id!=='blank'){ commit(); applyTemplate(tpl, boardId); const bd=S.els[boardId]; if(!bd.content.title) bd.content.title=tpl.name; render(); save(); } startEdit(boardId,'.bt'); }; }
$('#templates').onclick=()=>{ modal(`<h2>Templates</h2><p>Adds the structure to the current board (<b>${esc(S.els[S.cur].content.title||'Home')}</b>), next to what is already there.</p>${templateGrid()}`,'wide'); $('#modal-box').onclick=ev=>{ const b=ev.target.closest('[data-t]'); if(!b) return; const tpl=TEMPLATES.find(t=>t.id===b.dataset.t); closeModal(); if(tpl.id==='blank') return; commit(); const kids=canvasKids(S.cur); const bb=kids.length?bboxOf(kids):{x0:40,y0:40,x1:0,y1:40}; applyTemplate(tpl, S.cur, {x:40, y: kids.length? bb.y1+80 : 40}); render(); save(); setTimeout(fitAll,30); toast('Template "'+tpl.name+'" added'); }; };

