document.addEventListener('paste', async ev=>{ if(ev.target.isContentEditable || ['INPUT','TEXTAREA'].includes(ev.target.tagName)) return; const cd=ev.clipboardData; const files=[...cd.files];
  if(files.length){ ev.preventDefault(); commit(); for(const f of files) await addAnyFile(f,{section:'inbox'}); S.inboxOpen=true; render(); save(); toast('Pasted into Unsorted'); return; }
  const txt=cd.getData('text/plain').trim(); if(!txt) return; ev.preventDefault(); if(txt==='space:clip'){ pasteClip(); return; } commit(); pasteText(txt); S.inboxOpen=true; render(); save(); });
function pasteText(txt, where){ const w=where||{section:'inbox'}; const into=w.section==='canvas'?'board':'Unsorted'; let e;
  if(/^https?:\/\/\S+$/i.test(txt)){ if(/\.(png|jpe?g|gif|webp|svg)(\?|$)/i.test(txt)){ e=mk('image',{content:{blobId:null,url:txt,w:0,h:0,caption:''}}); Object.assign(e,w); addEl(e); toast('Image pasted into '+into); } else { e=mk('link',{content:{url:txt,title:'',preview:null}}); Object.assign(e,w); setLink(e,txt,''); addEl(e); toast('Link pasted into '+into); } }
  else { e=mk('note',{content:{html:esc(txt).split(/\n+/).map(l=>`<p>${l}</p>`).join('')}}); Object.assign(e,w); addEl(e); toast('Note pasted into '+into); }
  return e; }
async function pasteFromClipboard(pos){ const where={section:'canvas',x:snap(pos.x),y:snap(pos.y)}; if(S.clip){ try{ const t=await navigator.clipboard?.readText(); if(t==='space:clip'){ pasteClip(); return; } }catch{} }
  try{ const items=await navigator.clipboard.read(); let did=false; for(const it of items){ const imgType=it.types.find(t=>t.startsWith('image/')); if(imgType){ const blob=await it.getType(imgType); if(!did) commit(); await addImageFile(new File([blob],'pasted.'+imgType.split('/')[1],{type:imgType}), {...where}); where.x+=GRID*2; where.y+=GRID*2; did=true; continue; } if(it.types.includes('text/plain')){ const txt=(await (await it.getType('text/plain')).text()).trim(); if(!txt) continue; if(txt==='space:clip'){ pasteClip(); return; } if(!did) commit(); pasteText(txt,{...where}); did=true; } }
    if(did){ render(); save(); } else toast('Nothing to paste'); }
  catch(err){ toast('Clipboard blocked by the browser — use ⌘V instead'); } }
stage.addEventListener('dragover', ev=>{ ev.preventDefault(); }); $('#inbox').addEventListener('dragover', ev=>ev.preventDefault());
stage.addEventListener('drop', async ev=>{ ev.preventDefault(); const files=[...ev.dataTransfer.files]; if(files.length){ commit(); const p=toWorld(ev.clientX,ev.clientY); let i=0; for(const f of files){ await addAnyFile(f,{section:'canvas',x:snap(p.x+i*30),y:snap(p.y+i*30)}); i++; } render(); save(); return; } const url=ev.dataTransfer.getData('text/uri-list')||ev.dataTransfer.getData('text/plain'); if(url&&/^https?:\/\//i.test(url.trim())){ commit(); const p=toWorld(ev.clientX,ev.clientY); const e=mk('link',{x:snap(p.x),y:snap(p.y),content:{url:url.trim(),title:'',preview:null}}); setLink(e,url.trim(),''); addEl(e); render(); save(); } });
$('#inbox').addEventListener('drop', async ev=>{ ev.preventDefault(); const files=[...ev.dataTransfer.files]; if(!files.length) return; commit(); for(const f of files) await addAnyFile(f,{section:'inbox'}); render(); save(); });

