const cmenu=$('#cmenu');
const BG_SWATCHES={none:null,dark:'#1c1c1e',grey:'#3a3a3c',navy:'#1e2a44',green:'#1f3a2a',wine:'#3a1f2a',sand:'#e8dfcf',sky:'#d6e6f5',mint:'#dcefe2',rose:'#f5dde3',white:'#f7f7f9'};
let cmenuPos=null;
function showCmenu(ev){ cmenu.style.display='flex'; const w=cmenu.offsetWidth||230,h=cmenu.offsetHeight||260; cmenu.style.left=Math.min(ev.clientX, innerWidth-w-8)+'px'; const top=Math.min(ev.clientY, innerHeight-h-8); cmenu.style.top=top+'px'; cmenu.classList.toggle('up', top+h+140>innerHeight); }
function stageMenu(ev){ ev.preventDefault(); cmenuPos=toWorld(ev.clientX,ev.clientY); const cur=S.els[S.cur]; const isDefault=!cur.content.bg; const showGrid=!cur.content.noGrid;
  const NEW=[['note','New Note'],['link','New Link'],['tasks','New To-do'],['line','New Line'],['board','New Board'],['column','New Column'],['comment','New Comment']];
  const secs=[];
  if(S.clip) secs.push(`<button data-a="paste"><span class="lb">Paste</span><span class="kbd">⌘V</span></button>`);
  if(S.undo.length||S.redo.length) secs.push(`${S.undo.length?`<button data-a="undo"><span class="lb">Undo</span><span class="kbd">⌘Z</span></button>`:''}${S.redo.length?`<button data-a="redo"><span class="lb">Redo</span><span class="kbd">⌘⇧Z</span></button>`:''}`);
  if(canvasKids(S.cur).length) secs.push(`<button data-a="selall"><span class="lb">Select All</span><span class="kbd">⌘A</span></button>`);
  secs.push(NEW.map(([k,l])=>`<button data-a="new" data-t="${k}"><span class="lb">${l}</span></button>`).join(''));
  secs.push(`<div class="sub"><button data-a="bgmenu"><span class="lb">Change Board Background</span><span class="chev">${ICONS.chevdown}</span></button><div class="flyout list"><button data-a="bgcustom"><span class="lb">Choose Custom Color</span></button><div class="vs"></div><button data-a="bggrid"><span class="ck ${showGrid?'on':''}">${ICONS.check}</span><span class="lb">Show Dot Grid</span></button>${isDefault?'':`<div class="vs"></div><button data-a="bgreset"><span class="lb">Revert to Default</span></button>`}</div></div>`);
  secs.push(`<button data-a="new" data-t="image"><span class="lb">New Image/File Placeholder</span></button>`);
  cmenu.innerHTML=secs.join('<div class="vs"></div>'); cmenu.classList.remove('el-menu'); showCmenu(ev); }
document.addEventListener('contextmenu', ev=>{ const lh=ev.target.closest('#lines .hit'); const n=ev.target.closest('.el'); if(ev.target.isContentEditable || ['INPUT','TEXTAREA'].includes(ev.target.tagName)) return; if(ev.target.closest('#ghost,#modal,.pop,#cmenu')) return; if(!n&&!lh){ if(ev.target.closest('#stage') && !ev.target.closest('#zoomhud')) stageMenu(ev); else if(ev.target.closest('#inbox')){ ev.preventDefault(); } return; } ev.preventDefault(); const inner = n && n.closest('.items') && n!==n.closest('#world > .el') ? n.dataset.id : null; const id= lh? lh.dataset.id : (inner || n.closest('#world > .el')?.dataset.id || n.dataset.id); if(!S.sel.has(id)) select([id]);
  openElementMenu(ev.clientX, ev.clientY, false); });
cmenu.addEventListener('click', ev=>{ const b=ev.target.closest('button'); if(!b||b.disabled) return; const a=b.dataset.a; if(a==='bgmenu'){ b.parentElement.classList.toggle('open'); return; } cmenu.style.display='none';
  if(cmenu.classList.contains('el-menu')) return runElAction(a);
  if(a==='undo') return undo(); if(a==='redo') return redo(); if(a==='selall') return select(canvasKids(S.cur).map(e=>e.id));
  if(a==='paste'){ pasteClipAt(cmenuPos); return; }
  if(a==='bgcustom') return chooseBoardColor();
  if(a==='bggrid'){ commit(); const b0=S.els[S.cur]; b0.content.noGrid=!b0.content.noGrid; applyBoardBg(); save(); return; }
  if(a==='bgreset'){ commit(); S.els[S.cur].content.bg=null; applyBoardBg(); save(); return; }
  if(a==='new'){ const t=b.dataset.t; const pos={x:snap(cmenuPos.x),y:snap(cmenuPos.y)}; if(t==='image'){ commit(); const e=mk('image'); e.x=pos.x; e.y=pos.y; addEl(e); S.sel.clear(); S.sel.add(e.id); render(); save(); } else { createFromTool(t,pos); } return; } });
document.addEventListener('pointerdown', ev=>{ if(!ev.target.closest('#cmenu')) cmenu.style.display='none'; if(!ev.target.closest('#tools, .pop')) closePop(); }, true);

/* ============ teclado ============ */
document.addEventListener('keydown', ev=>{
  const mod=ev.metaKey||ev.ctrlKey; const typing=ev.target.isContentEditable||['INPUT','TEXTAREA'].includes(ev.target.tagName);
  if(ev.key==='Escape'){ if($('#lightbox').classList.contains('open')){ $('#lightbox').classList.remove('open'); return; } if($('#modal').classList.contains('open')) { closeModal(); return; } if(S.present){ togglePresent(); return; } if(typing){ ev.target.blur(); stopEdit(); return; } if(S.draw){ toggleDraw(); return; } closePop(); deselect(); return; }
  if(mod && ev.key.toLowerCase()==='f'){ ev.preventDefault(); openSearch(); return; }
  if(typing && ev.key==='Tab' && ev.target.closest('.body')){ ev.preventDefault(); indentText(ev.shiftKey?-1:1); return; }
  if(typing){ if(mod && ev.key==='Enter'){ ev.preventDefault(); const id=S.editing||ev.target.closest('.el')?.dataset.id; ev.target.blur(); stopEdit(); if(id){ const e=S.els[id]; if(e&&e.section==='canvas'){ const n=nodesFor(id)[0]; commit(); const ne=mk(e.type==='board'?'note':e.type); ne.x=e.x; ne.y=snap(e.y+(n?.offsetHeight||100)+GRID); if(e.w) ne.w=e.w; addEl(ne); if(ne.type==='tasks'){ const t=mk('task',{parentId:ne.id,section:'list',index:0}); S.els[t.id]=t; } S.sel.clear(); S.sel.add(ne.id); render(); save(); startEdit(ne.id, ne.type==='note'?'.body':ne.type==='column'?'.ct':ne.type==='tasks'?'.tt':'.lt'); } } }
    if(mod && ev.target.closest('.body')){ const k=ev.key.toLowerCase(); const run=c=>{ ev.preventDefault(); document.execCommand(c.cmd,false,c.v); }; if(k==='b') run({cmd:'bold'}); else if(k==='i') run({cmd:'italic'}); else if(k==='u'&&!ev.shiftKey) run({cmd:'underline'}); else if(ev.shiftKey&&ev.key==='1'){ ev.preventDefault(); applyBlockStyle('h1'); } else if(ev.shiftKey&&ev.key==='2'){ ev.preventDefault(); applyBlockStyle('h2'); } else if(ev.shiftKey&&ev.key==='0'){ ev.preventDefault(); applyBlockStyle('p'); } else if(ev.shiftKey&&ev.key==='9'){ ev.preventDefault(); applyBlockStyle('small'); } else if(ev.shiftKey&&k==='u') run({cmd:'insertUnorderedList'}); else if(ev.shiftKey&&k==='o') run({cmd:'insertOrderedList'}); else if(ev.shiftKey&&k==='x') run({cmd:'strikeThrough'}); else if(k==='j') { ev.preventDefault(); applyInline('bg','yellow'); } else if(k==='k'){ ev.preventDefault(); $('#tools [data-tool="tlink"]')?.click(); } else if(ev.key==='\\'){ ev.preventDefault(); toggleCenter(); } }
    return; }
  if(ev.code==='Space' && !spaceDown){ spaceDown=true; stage.classList.add('pan-ready'); ev.preventDefault(); return; }
  if(mod && ev.altKey && ev.key.toLowerCase()==='p'){ ev.preventDefault(); togglePresent(); return; }
  if(mod && ev.key.toLowerCase()==='z'){ ev.preventDefault(); ev.shiftKey?redo():undo(); return; }
  if(mod && ev.shiftKey && ev.key.toLowerCase()==='d'){ ev.preventDefault(); toggleTheme(); return; }
  if(mod && ev.key.toLowerCase()==='d'){ ev.preventDefault(); duplicate(); return; }
  if(mod && ev.key.toLowerCase()==='c'){ ev.preventDefault(); copySel(); return; }
  if(mod && ev.key.toLowerCase()==='a'){ ev.preventDefault(); select(canvasKids(S.cur).map(e=>e.id)); return; }
  if(mod && ev.key.toLowerCase()==='u'){ ev.preventDefault(); const b=S.els[S.cur]; if(b?.parentId) openBoard(b.parentId); return; }
  if(mod && ev.key.toLowerCase()==='l'){ ev.preventDefault(); toggleLock(); return; }
  if(mod && (ev.key==='='||ev.key==='+')){ ev.preventDefault(); zoomAt(1.2); return; }
  if(mod && ev.key==='-'){ ev.preventDefault(); zoomAt(1/1.2); return; }
  if(mod && ev.key==='0'){ ev.preventDefault(); const v=view(); zoomAt(1/v.z); return; }
  if(mod && ev.shiftKey && ev.key==='ArrowUp'){ ev.preventDefault(); zOrder(1); return; }
  if(mod && ev.shiftKey && ev.key==='ArrowDown'){ ev.preventDefault(); zOrder(-1); return; }
  if(ev.key==='Backspace'||ev.key==='Delete'){ ev.preventDefault(); delSel(); return; }
  if(ev.key==='z'||ev.key==='Z'){ fitAll(); return; }
  if((ev.key==='d'||ev.key==='D') && !mod){ toggleDraw(); return; }
  if(ev.key==='Enter' && S.sel.size===1){ const e=S.els[[...S.sel][0]]; if(e.type==='board'){ openBoard(e.id); return; } if(e.type==='image'){ openLightbox(e); return; } if(e.type==='doc'){ openDoc(e); return; } if(e.type==='sketch'){ openSketch(e); return; } const sel={note:'.body',column:'.ct',tasks:'.tt',link:'.lt',comment:'.cmt',map:'.mq'}[e.type]; if(sel){ ev.preventDefault(); startEdit(e.id,sel); } return; }
  if(ev.key.startsWith('Arrow') && S.sel.size){ ev.preventDefault(); const s=ev.shiftKey?GRID*5:GRID; nudge(ev.key==='ArrowLeft'?-s:ev.key==='ArrowRight'?s:0, ev.key==='ArrowUp'?-s:ev.key==='ArrowDown'?s:0); return; }
  if(ev.key==='?' ){ showHelp(); }
});
document.addEventListener('keyup', ev=>{ if(ev.code==='Space'){ spaceDown=false; stage.classList.remove('pan-ready'); } });
let pasteHandled=false; document.addEventListener('paste', ()=>{ pasteHandled=true; }, true);
document.addEventListener('keydown', ev=>{ const mod=ev.metaKey||ev.ctrlKey; if(mod&&!ev.altKey&&ev.key.toLowerCase()==='v'&&S.clip&&!ev.target.isContentEditable&&ev.target.tagName!=='INPUT'){ pasteHandled=false; setTimeout(()=>{ if(!pasteHandled) pasteClip(); },80); } });

/* ============ wheel, hud, tema ============ */
stage.addEventListener('wheel', ev=>{ ev.preventDefault(); if(ev.ctrlKey||ev.metaKey){ zoomAt(Math.exp(-clamp(ev.deltaY,-40,40)*0.008), ev.clientX, ev.clientY); } else { const v=view(); v.x-=ev.deltaX; v.y-=ev.deltaY; applyView(); clearTimeout(stage._wt); stage._wt=setTimeout(save,300); } }, {passive:false});
$('#zin').onclick=()=>zoomAt(1.2); $('#zout').onclick=()=>zoomAt(1/1.2); $('#zpct').onclick=()=>zoomAt(1/view().z); $('#fit').onclick=fitAll; $('#undo').onclick=undo; $('#redo').onclick=redo;
$('#inbox-btn').onclick=$('#inbox-tab').onclick=()=>{ S.inboxOpen=!S.inboxOpen; $('#inbox').classList.toggle('open',S.inboxOpen); $('#app').classList.toggle('inbox-open',S.inboxOpen); save(); };
$('#inbox-close').onclick=()=>{ S.inboxOpen=false; $('#inbox').classList.remove('open'); $('#app').classList.remove('inbox-open'); save(); };
$('#title').addEventListener('keydown', ev=>{ if(ev.key==='Enter'){ ev.preventDefault(); ev.target.blur(); } });
function toggleTheme(){ const cur=document.documentElement.getAttribute('data-theme'); const sys=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'; const now=cur||sys; const next=now==='dark'?'light':'dark'; document.documentElement.setAttribute('data-theme',next); try{ localStorage.setItem('space-theme',next); }catch{} syncThemeIcon(); }
function syncThemeIcon(){ const b=$('#theme'); if(!b) return; const dark=(document.documentElement.getAttribute('data-theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'))==='dark'; const svg=b.querySelector('svg'); if(svg) svg.outerHTML=ICONS[dark?'sun':'moon']; }
$('#theme').onclick=toggleTheme; try{ const t=localStorage.getItem('space-theme'); document.documentElement.setAttribute('data-theme',t||'dark'); }catch{ document.documentElement.setAttribute('data-theme','dark'); }
function showHelp(){ const SECS=[['The basics',[['New note','Double-click the board'],['Add another note, board or column','⌘ ↩'],['Deselect / stop editing','Esc'],['Edit the selected card','↩'],['Multi-select','⇧ click or drag on the board'],['Delete object','⌫'],['Move object to Unsorted','⌥ `'],['Duplicate','⌘ D, or hold ⌥ while dragging'],['Cut / copy / paste','⌘ X / C / V'],['Paste styles','⌘ ⌥ V'],['Select all','⌘ A'],['Undo / redo','⌘ Z / ⌘ ⇧ Z'],['Nudge an object','Arrows (⇧ for more)'],['Bring forward / send back','⌘ ⇧ ↑ / ↓'],['Connect selected with lines','⌘ K'],['Search','⌘ F'],['Presentation mode','⌘ ⌥ P'],['Start drawing','⇧ D']]],
  ['Arrange',[['Align top / left / bottom / right','⌥ W / A / S / D'],['Align center horizontally / vertically','⌥ H / ⌥ V'],['Distribute vertically / horizontally','⌘ ⌥ ⇧ V / H']]],
  ['Navigation',[['Move around the board','Hold Space and drag'],['Go to parent board','⌘ U'],['Go back into the last board','⌘ ⇧ U']]],
  ['Zoom & appearance',[['Zoom in / out','⌘ + / ⌘ −'],['Reset to 100%','⌘ 0'],['Scale to fit','Z'],['Smaller / larger interface','⌘ ⇧ , / ⌘ ⇧ .'],['Toggle dark mode','⌘ ⇧ D']]],
  ['Text formatting',[['Bold / italic / underline','⌘ B / I / U'],['Strikethrough','⌘ ⇧ X'],['Large heading / normal heading','⌘ ⇧ 1 / 2'],['Normal text / small text','⌘ ⇧ 0 / 9'],['Bullet / numbered list','⌘ ⇧ U / O'],['Indent / un-indent','Tab / ⇧ Tab'],['Highlight','⌘ J'],['Hyperlink','⌘ K'],['Align center','⌘ \\']]],
  ['Markdown',[['Large heading','# then space'],['Normal heading','## then space'],['Bullet list','* then space'],['Numbered list','1. then space'],['Checkbox','[] then space'],['Quote','> then space'],['Callout','! then space'],['Code block','``` then space'],['Divider line','---']]]];
  modal(`<h2>Shortcuts</h2>${SECS.map(([h,rows])=>`<h3>${h}</h3><table>${rows.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')}</table>`).join('')}<p class="tip">Press / to show shortcuts</p><div class="row"><button class="btn" id="hclose">Close</button></div>`); $('#hclose').onclick=closeModal; }
$('#help').onclick=showHelp;

